import{z as B,x as A,o as l,c as p,q as i,j as E,D as t,d as r,s as n,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"页面置换的竞争分析","description":"","frontmatter":{"title":"页面置换的竞争分析","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/paging-competitive.md","filePath":"cs/paging-competitive.md","lastUpdated":1791413859000}'),d={name:"cs/paging-competitive.md"};function k(m,a,h,c,C,F){const o=A("Mermaid");return l(),p("div",null,[a[2]||(a[2]=i('<h1 id="页面置换的竞争分析" tabindex="-1">页面置换的竞争分析 <a class="header-anchor" href="#页面置换的竞争分析" aria-label="Permalink to &quot;页面置换的竞争分析&quot;">​</a></h1><div class="epigraph"><p>$k$ 槽缓存，缺页代价 1；FIFO/LRU 对确定性对手 $k$-竞争，最优离线是 Belady 最远未来。</p><footer>—— 据 Sleator and Tarjan, 1985；Belady, A Study of Replacement Algorithms, 1966；CLRS 第 15 章对照整理</footer></div><p>上一课<a href="/cs/competitive-ratio">在线算法与竞争比</a>定义了 \\(\\rho\\)。本课把它用在操作系统的页面置换上：缺口是 LRU/FIFO 的 \\(k\\)-竞争证明，以及确定性算法的下界 \\(k\\)。竞争比定义不重写，具体内核的 LRU 近似实现也不写。后课租买是更干净的 2-竞争原型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>模型：请求序列 \\(p_1,p_2,\\ldots\\) 进 \\(k\\) 个槽的缓存，请求页不在槽内即缺页，代价 \\(1\\)，须换出一页。离线最优是 Belady 的 MIN：换出未来最远才再用的页。在线侧，LRU 换出最久未用的页。Sleator–Tarjan 的结论：LRU 与 FIFO 都是 \\(k\\)-竞争，而任何确定性算法竞争比不低于 \\(k\\)——下界恰好被 LRU 达到。随机化能突破确定性下界：标记算法对 oblivious 对手约 \\(H_k\\)-竞争，\\(H_k\\) 是调和数，量级 \\(\\ln k\\)。</p><p>缺口是缓存这一问题的竞争分析；列表更新出自同一篇论文，本课不碰。</p><p><span class="marginnote">术语翻译：竞争比 \\(\\rho\\) 就是「在线算法的最坏代价 ÷ 开挂知道未来的离线最优代价」，对一切请求序列取最大值。\\(k\\)-竞争即最坏情形下在线缺页数不超过最优的 \\(k\\) 倍——这是逐请求的最坏保证，不是平均表现的说法。</span></p><h3 id="不是工作集调参" tabindex="-1">不是工作集调参 <a class="header-anchor" href="#不是工作集调参" aria-label="Permalink to &quot;不是工作集调参&quot;">​</a></h3><p>竞争比是对最坏输入的逐请求保证，不依赖输入分布。这与统计调参不同一层次：工作集模型是实践启发式，参数调得好只说明平均表现好，不是 \\(\\rho\\) 的证明，不要把调参当证明。</p><p><span class="marginnote">Belady 1966 离线最优。Sleator–Tarjan 1985 给出在线的 \\(k\\)-竞争与下界。后课 ski-rental 是更干净的 2-竞争。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>上界用势函数：取在线缓存与 OPT 缓存的对称差大小为势。OPT 每缺一次页，势至多增加 \\(k\\)（换入一页、差集成员至多被换出 \\(k\\) 个），而在线每缺一次页势减一；配平即得在线缺页数 \\(\\le k\\cdot\\) OPT 缺页数。下界用对手构造：让对手交错请求 \\(k+1\\) 页，确定性算法的缓存里永远缺着下一步要请求的那页，OPT 按最远未来策略只偶尔缺。</p><p><span class="marginnote">势函数可以想象成「欠条本」：两份缓存每差一页就记一笔账。最优每缺一次最多欠 \\(k\\) 笔，在线每缺一次销掉一笔；欠条总数有上限，销账次数（在线缺页）自然不超过 \\(k\\) 乘最优缺页次数——这就是「配平」二字的全部含义。</span></p>',13)),(l(),E(s,null,{default:t(()=>[n(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E9%A1%B5%E9%9D%A2%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20LRU%5B%22LRU%20%2F%20FIFO%22%5D%0A%20%20LRU%20--%3E%20K%5B%22k-%E7%AB%9E%E4%BA%89%22%5D%0A%20%20OFF%5B%22Belady%20MIN%22%5D%20--%3E%20OPT%5B%22%E7%A6%BB%E7%BA%BF%E6%9C%80%E4%BC%98%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"写回磁盘的代价可以折进模型，本课按单位缺页计。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"\\(k\\) 这个比来自槽位数本身：OPT 每缺一次可以承担在线 \\(k\\) 次缺页的势债，最优常数因此压不过 \\(k\\)；对手的策略就是总去请求在线缓存里没有的那页。同一问题是 \\(k\\)-server 在均匀度量空间上的特例。OS 课讲的时钟算法等是 LRU 的硬件便宜近似；本课谈的是竞争意义下的 LRU 本身。",-1)),a[6]||(a[6]=e("p",null,"上面那张图是「谁对谁、结论是什么」；下界证明里对手怎么把确定性算法玩弄于股掌，值得单独看一遍：以 \\(k=2\\)、请求集 \\(\\{A,B,C\\}\\) 为例。",-1)),(l(),E(s,null,{default:t(()=>[n(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%9C%A8%E7%BA%BF%E7%BC%93%E5%AD%98%E5%8F%AA%E8%A3%85%202%20%E9%A1%B5%22%5D%20--%3E%20L%5B%22%E5%AF%B9%E6%89%8B%E4%BA%A4%E9%94%99%E8%AF%B7%E6%B1%82%20A%20B%20C%22%5D%0A%20%20L%20--%3E%20Q%7B%22%E4%B8%8B%E4%B8%80%E9%A1%B5%E6%81%B0%E4%B8%8D%E5%9C%A8%E5%9C%A8%E7%BA%BF%E7%BC%93%E5%AD%98%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%9E%84%E9%80%A0%E4%BF%9D%E8%AF%81%E4%BA%86%E8%BF%99%E4%B8%80%E7%82%B9%22%7C%20M%5B%22%E7%A1%AE%E5%AE%9A%E6%80%A7%E5%9C%A8%E7%BA%BF%E7%BC%BA%E9%A1%B5%201%20%E6%AC%A1%22%5D%0A%20%20Q%20--%3E%20O%5B%22OPT%20%E6%8C%89%E6%9C%80%E8%BF%9C%E6%9C%AA%E6%9D%A5%E6%8D%A2%20%E5%8F%AA%E5%81%B6%E5%B0%94%E7%BC%BA%22%5D%0A%20%20M%20--%3E%20L%0A%20%20O%20--%3E%20L%0A%20%20M%20--%3E%20R%5B%22%E7%BC%BA%E9%A1%B5%E6%95%B0%E6%AF%94%E5%80%BC%E7%B4%AF%E7%A7%AF%E9%80%BC%E8%BF%91%20k%3A1%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 ARC 等自适应策略，也不写多层缓存。后课默认：分页语境下 LRU 是 \\(k\\)-竞争，确定性下界即 \\(k\\)。下一课租买问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LRU/FIFO 确定性 \\(k\\)-竞争，确定性下界恰为 \\(k\\)。</li><li>离线最优是 Belady 的最远未来策略。</li><li>随机化对 oblivious 对手可压到 \\(H_k\\)。</li><li>出处：Sleator and Tarjan, 1985；Belady, 1966。</li></ul><p><span class="marginnote">数字实例：\\(k=3\\) 时调和数 \\(H_3 = 1 + \\frac{1}{2} + \\frac{1}{3} \\approx 1.83\\)，随机化把竞争比从 3 压到约 1.83；\\(k\\) 越大 \\(H_k\\) 只按 \\(\\ln k\\) 缓慢增长，优势越大。前提是对手看不到随机数——若对手能偷看你的硬币，随机化就白搭。</span></p>',5))])}const f=B(d,[["render",k]]);export{_ as __pageData,f as default};
